"use client";

/**
 * Tap to record on the coach composer. The existing controller still owns all three
 * listening routes; this button only starts and stops a session.
 *
 * A button, and nothing else. The controller reports its state through `view()`.
 *
 * ONE controller, for the life of the component. The parent hands its callbacks down as inline
 * arrows, so they are new on every render; the controller reads them through a ref that is
 * refreshed after each one (`lib/coach/hold-ports.ts`). A controller keyed on those callbacks was
 * rebuilt — and the hold in progress cancelled — by the very re-render the press itself caused.
 */

import { useEffect, useState, useSyncExternalStore } from "react";
import { HoldController, type HoldView } from "@/lib/coach/hold";
import { latestCallbackPorts, type HoldCallbacks } from "@/lib/coach/hold-ports";
import { micAvailable, startListening } from "@/lib/coach/speech-api";
import { openMicRecorder } from "@/lib/capture-mic";
import { transcribeClip } from "@/lib/coach-transcribe-client";
import { createListener, isStandalone, liveCapable } from "@/lib/voice/choose-listener";
import { preloadLive, startLive } from "@/lib/voice/live-io";
import { SendGlyph } from "@/components/coach/round-button";

export type CoachMicProps = {
  /** What is in the composer right now, so a failed recording can put it back. */
  readBox: () => string;
  /** Put the live transcript — or the fallback's answer — into the composer. */
  writeBox: (text: string) => void;
  /** The composer's disabled state — offline, restoring, or a turn in flight. */
  disabled: boolean;
  /** The typed path's explicit Send action. */
  onSend: (text: string) => void;
  /** A draft outside active editing makes the one main control Send. */
  readyToSend: boolean;
  onRecordPointerDown: () => void;
  onRecordPointerDone: () => void;
  /** True while dictation owns the composer: textarea read-only, Send disabled. */
  onListening: (locked: boolean) => void;
  /** One line under the composer, or null. */
  onNotice: (copy: string | null) => void;
};

const IDLE: HoldView = {
  locked: false, listening: false, recording: false, secondsLeft: 0, busy: false,
  settling: false, notice: null,
};

/** Never subscribes: the answer is a fact about this page load, asked once on the client. */
const noSubscription = (): (() => void) => () => {};

export default function CoachMic({
  readBox, writeBox, disabled, onSend, readyToSend,
  onRecordPointerDown, onRecordPointerDone, onListening, onNotice,
}: CoachMicProps) {
  const [view, setView] = useState<HoldView>(IDLE);

  /**
   * §3's last row. The server renders neither API, so it renders no mic; the phone answers for
   * itself after hydration. Whether the mic WORKS is asked again at press time.
   */
  const available = useSyncExternalStore(noSubscription, micAvailable, () => false);

  /**
   * The controller and its ports, built ONCE together. The ports hold the parent's callbacks in a
   * closure and the component refreshes them by calling `update` after every render — so the
   * parent may hand down new inline arrows as often as it likes and the controller never changes.
   */
  const [rig] = useState(() => {
    // Phase 14 slice 1: in the installed app a hold streams to live dictation first; in a browser
    // tab the on-device recogniser stays first (lib/voice/choose-listener.ts).
    const listener = createListener({
      standalone: () => isStandalone(), liveCapable: () => liveCapable(),
      startDevice: (handlers) => startListening(handlers), startLive,
    });
    const built = latestCallbackPorts(
      { readBox, writeBox, send: onSend, publish: () => {} } as HoldCallbacks,
      {
        listen: (handlers) => listener.listen(handlers),
        record: (handlers) => openMicRecorder(handlers),
        transcribe: (clip) => transcribeClip(clip),
      },
    );
    return { update: built.update, hold: new HoldController(built.ports, "tap") };
  });
  const hold = rig.hold;

  // No dependency array on purpose: the parent passes inline arrows, so its callbacks are new on
  // every render and the controller must always be holding the current ones. They are read only
  // from an event handler, which runs after this has refreshed them.
  useEffect(() => {
    rig.update({
      readBox, writeBox, send: onSend,
      publish: (next) => { setView(next); onListening(next.locked); onNotice(next.notice); },
    });
  });

  // Fetch the Live SDK while the user is still reading, so the first tap does not wait for it.
  useEffect(() => { if (isStandalone() && liveCapable()) preloadLive(); }, []);

  useEffect(() => {
    // A recording that outlives the page is a microphone left on. `pagehide` is the one iOS Safari
    // reliably fires; `visibilitychange` covers a tab switch on everything else. `hold` is stable,
    // so this cleanup runs on unmount and nowhere else.
    const end = (): void => hold.cancel();
    const hidden = (): void => { if (document.visibilityState === "hidden") hold.cancel(); };
    window.addEventListener("pagehide", end);
    document.addEventListener("visibilitychange", hidden);
    return () => {
      window.removeEventListener("pagehide", end);
      document.removeEventListener("visibilitychange", hidden);
      hold.cancel();
    };
  }, [hold]);

  const mode = view.busy || view.settling ? "busy"
    : view.listening ? "stop"
    : readyToSend ? "send" : "record";
  if (!available && mode === "record") return null;

  return (
    <button
      type="button"
      data-composer-action
      data-composer-main
      onPointerDown={() => { if (mode === "record") onRecordPointerDown(); }}
      onPointerUp={onRecordPointerDone}
      onPointerCancel={onRecordPointerDone}
      onClick={() => {
        onRecordPointerDone();
        if (mode === "send") onSend(readBox());
        else if (mode === "record" || mode === "stop") hold.toggleTap();
      }}
      disabled={mode === "busy" || (mode !== "stop" && disabled)}
      aria-label={mode === "busy" ? "Transcribing voice message"
        : mode === "stop" ? "Stop recording" : mode === "send" ? "Send" : "Record message"}
      aria-pressed={mode === "record" || mode === "stop" ? mode === "stop" : undefined}
      className={`tap flex shrink-0 items-center justify-center rounded-full disabled:opacity-40${mode === "stop" ? " coach-recording-button" : ""}`}
      style={{
        width: 44, height: 44,
        // At rest the same round white button as the chat box's others; red while it records.
        color: mode === "stop" ? "var(--color-text-primary)" : "var(--color-on-primary)",
        background: mode === "stop" ? "var(--color-alert)" : "var(--grad-ink)",
      }}
    >
      {mode === "busy" ? <span aria-hidden="true">…</span> : mode === "send" ? <SendGlyph /> : mode === "stop" ? (
        <span className=" tabular-nums" style={{ fontSize: 14, fontWeight: 400 }}>
          {view.recording ? view.secondsLeft : <svg width="17" height="17" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="5" y="5" width="14" height="14" rx="2" /></svg>}
        </span>
      ) : (
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"
          stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
          <rect x="9" y="3" width="6" height="12" rx="3" />
          <path d="M5 11a7 7 0 0 0 14 0" />
          <path d="M12 18v3" />
        </svg>
      )}
    </button>
  );
}

files.components/coach/Composer.tsx:
"use client";

import type { ReactNode } from "react";
import CoachMic from "@/components/CoachMic";
import { Round, SendGlyph } from "@/components/coach/round-button";
import { useComposerInput } from "@/components/coach/use-composer-input";
import { COMPOSER_OFFLINE_COPY } from "@/lib/coach/chat-state";
import { ASSISTANT_NAME } from "@/lib/brand";

export default function Composer({
  disabled, offline, onSend, toolbar,
}: {
  disabled: boolean;
  offline: boolean;
  onSend: (text: string) => void | boolean;
  toolbar?: ReactNode;
}) {
  const controls = useComposerInput(disabled, onSend);
  const { input, draft, editing, listening, micNotice, readBox, send } = controls;

  return (
    <div data-testid="coach-composer" className="relative flex shrink-0 flex-col gap-1">
      <div data-testid="coach-composer-box" className="glass flex flex-col gap-2 rounded-3xl"
        style={{ padding: 12 }}>
        <label htmlFor="coach-message" className="px-1 text-tiny font-normal text-muted"><span>Message {ASSISTANT_NAME}</span></label>
        <textarea id="coach-message" ref={input} rows={1} maxLength={2000}
          disabled={disabled} readOnly={listening}
          placeholder={offline ? COMPOSER_OFFLINE_COPY : `Ask ${ASSISTANT_NAME}`}
          aria-label={`Message ${ASSISTANT_NAME}`}
          className="min-h-[44px] w-full resize-none bg-transparent px-1 outline-none placeholder:text-muted disabled:opacity-40"
          style={{ fontSize: "var(--text-body-md)", fontWeight: "var(--font-weight-body-md)", color: "var(--color-text-primary)" }}
          {...controls.textEvents}
        />
        <div data-testid="coach-composer-row" className="flex items-center justify-between gap-2">
          <div className="flex min-w-0 items-center gap-1">
            {toolbar && <div data-testid="coach-composer-toolbar">{toolbar}</div>}
          </div>
          <div className="flex shrink-0 items-center gap-1">
            {editing && draft.trim() && !listening && <button type="button" aria-label="Send"
              data-composer-action disabled={disabled} onClick={() => send(readBox())}
              className="tap flex shrink-0 items-center justify-center bg-transparent disabled:opacity-40">
              <Round><SendGlyph /></Round>
            </button>}
            <CoachMic {...controls.micEvents} disabled={disabled} />
          </div>
        </div>
      </div>
      {micNotice && <p role="status" className="m-0"
        style={{ fontSize: 12, fontWeight: 400, color: "var(--color-text-muted)" }}>{micNotice}</p>}
    </div>
  );
}

files.components/coach/use-composer-input.ts:
"use client";

import { useRef, useState, type FocusEvent, type KeyboardEvent } from "react";

export function useComposerInput(disabled: boolean, onSend: (text: string) => void | boolean) {
  const input = useRef<HTMLTextAreaElement>(null);
  const composing = useRef(false);
  const recordPointerDown = useRef(false);
  const [draft, setDraft] = useState("");
  const [editing, setEditing] = useState(false);
  const [listening, setListening] = useState(false);
  const [micNotice, setMicNotice] = useState<string | null>(null);

  const send = (text: string) => {
    if (!text.trim() || disabled || listening) return;
    if (onSend(text) !== false && input.current) {
      input.current.value = "";
      setDraft("");
      setEditing(false);
    }
  };
  const readBox = () => input.current?.value ?? "";
  const textEvents = {
    onChange: (event: { currentTarget: HTMLTextAreaElement }) => {
      setDraft(event.currentTarget.value);
      setEditing(true);
    },
    onFocus: () => setEditing(true),
    onClick: () => setEditing(true),
    onSelect: () => setEditing(true),
    onBlur: (event: FocusEvent<HTMLTextAreaElement>) => {
      const toAction = (event.relatedTarget as HTMLElement | null)
        ?.closest?.("[data-composer-action]");
      if (!recordPointerDown.current && !toAction) setEditing(false);
    },
    onCompositionStart: () => { composing.current = true; },
    onCompositionEnd: () => { composing.current = false; },
    onKeyDown: (event: KeyboardEvent<HTMLTextAreaElement>) => {
      if (event.key === "Enter" && !event.shiftKey && !composing.current
        && !event.nativeEvent.isComposing && event.keyCode !== 229) {
        event.preventDefault();
        send(event.currentTarget.value);
      }
    },
  };
  const micEvents = {
    readBox,
    writeBox: (text: string) => {
      if (input.current) input.current.value = text;
      setDraft(text);
    },
    onSend: send,
    readyToSend: Boolean(draft.trim()) && !editing,
    onRecordPointerDown: () => { recordPointerDown.current = true; },
    onRecordPointerDone: () => { recordPointerDown.current = false; },
    onListening: (locked: boolean) => {
      setListening(locked);
      if (!locked) setEditing(false);
    },
    onNotice: setMicNotice,
  };
  return { input, draft, editing, listening, micNotice, readBox, send, textEvents, micEvents };
}

files.lib/coach/hold.ts:
"use client";

/** One speech session. Hold preserves T7 behavior; tap records until the next click. */

import {
  EMPTY_COPY, EMPTY_MS, FINALISE_MS, NO_SPEECH_COPY, TAP_MS,
  initialDictation, nextDictation, transcriptOf,
  type DictationEvent, type DictationNotice, type DictationState,
} from "@/lib/coach/dictation";
import type { SpeechHandlers, SpeechSession } from "@/lib/coach/speech-api";
import type { MicRecorder } from "@/lib/capture-mic";
import { MAX_RECORDING_SECONDS } from "@/lib/capture-mic";
import { discardRun, markMs } from "@/lib/timing";
import type { HoldPorts, HoldView } from "@/lib/coach/hold-ports";

export type { HoldPorts, HoldView } from "@/lib/coach/hold-ports";

/** Where the fallback's clip is. "flushing" and "transcribing" both mean: it is coming, use it. */
type ClipState = "none" | "opening" | "recording" | "flushing" | "transcribing";

/** The keyboard's stand-in for a pointer id, so a Space keyup cannot end a finger's hold. */
const KEYBOARD_POINTER = -1;

export class HoldController {
  private state: DictationState = initialDictation();
  private pointer: number | null = null;
  private holding = false;
  private session: SpeechSession | null = null;
  private recorder: MicRecorder | null = null;
  private clipState: ClipState = "none";
  private startTimer: unknown = null;
  private finaliseTimer: unknown = null;
  private noticeTimer: unknown = null;
  private audioStarted = false;
  private heard = false;
  private restarts = 0;
  private wantClip = false;
  private typed = "";
  private releasedAt = 0;
  private elapsed = 0;
  private notice: string | null = null;
  /** Guards late callbacks and awaited work after cancel or a new session. */
  private gen = 0;
  /** Words the on-device recogniser had already collected before the hold fell back to §2. */
  private carried = "";

  constructor(private readonly ports: HoldPorts, private readonly interaction: "hold" | "tap" = "hold") {}

  view(): HoldView {
    return {
      locked: this.holding || this.state.phase === "finalising" || this.clipState !== "none",
      listening: this.holding && this.state.phase === "listening",
      settling: !this.holding && (this.state.phase === "finalising" || this.clipState !== "none"),
      recording: this.clipState === "recording",
      secondsLeft: Math.max(0, Math.ceil(MAX_RECORDING_SECONDS - this.elapsed)),
      busy: this.clipState === "transcribing",
      notice: this.notice,
    };
  }

  press(pointerId?: number): void {
    if (this.holding || this.clipState !== "none" || this.state.phase === "finalising") return;
    this.gen += 1;
    this.carried = "";
    this.pointer = pointerId ?? KEYBOARD_POINTER;
    this.typed = this.ports.readBox();
    this.holding = true;
    this.heard = false;
    this.audioStarted = false;
    this.restarts = 0;
    this.releasedAt = 0;
    this.apply({ type: "press", at: this.now() });
    this.showNotice(null);
    if (this.interaction === "tap") {
      this.begin();
    } else {
      this.startTimer = this.setTimer(() => { this.startTimer = null; this.begin(); }, TAP_MS);
    }
    this.publish();
  }

  toggleTap(): void {
    if (this.interaction !== "tap") return;
    if (this.holding) this.release();
    else this.press();
  }

  release(pointerId?: number): void {
    if (!this.holding) return;
    // A different pointer cannot end a hold; tap mode always uses the keyboard sentinel.
    if (this.pointer !== null && (pointerId ?? KEYBOARD_POINTER) !== this.pointer) return;
    this.holding = false;
    this.pointer = null;
    this.releasedAt = this.now();

    if (this.startTimer !== null) {
      this.clearTimer(this.startTimer);
      this.startTimer = null;
      this.abandon(this.apply({ type: "release", at: this.releasedAt }).notice);
      return;
    }
    if (this.clipState !== "none") { this.releaseRecording(); return; }

    // `stop()` ends the utterance, not the session: the last final result still arrives.
    this.session?.stop();
    const next = this.apply({ type: "release", at: this.releaseEventTime() });
    if (next.phase === "idle") { this.abandon(next.notice); return; }
    if (next.phase === "sent" || next.phase === "empty") { this.settleSpeech(next); return; }
    if (!this.heard && !this.audioStarted) {
      // The microphone never opened. This was the permission sheet lifting their finger.
      this.session?.abort();
      this.session = null;
      this.quiet();
      return;
    }
    this.finaliseTimer = this.setTimer(() => {
      this.finaliseTimer = null;
      this.settleSpeech(this.apply({ type: "finalised" }));
    }, this.session?.finaliseMs ?? FINALISE_MS);
    this.publish();
  }

  /** The page is going away, or the component is unmounting: nothing is owed to anybody. */
  cancel(): void {
    this.gen += 1;
    this.wantClip = false;
    this.clearTimer(this.startTimer);
    this.clearTimer(this.finaliseTimer);
    this.startTimer = null;
    this.finaliseTimer = null;
    this.session?.abort();
    this.session = null;
    this.recorder?.cancel();
    this.recorder = null;
    this.clipState = "none";
    this.holding = false;
    this.pointer = null;
    if (this.state.phase === "idle") this.publish();
    else this.abandon(null);
  }

  // ------------------------------------------------------------- on-device §1

  private begin(): void {
    if (!this.holding) return;
    if (this.state.fallback) { void this.startRecording(); return; }
    const gen = this.gen;
    const session = this.ports.listen(this.handlers(gen));
    if (gen !== this.gen) { session?.abort(); return; }
    this.session = session;
    // `startListening` reports its own failure before answering null, and that may already have
    // abandoned the hold. Only a hold still standing gets a second permission sheet.
    if (this.session === null && this.holding) void this.startRecording();
  }

  private handlers(gen: number): SpeechHandlers {
    return {
      onSegment: (segment) => {
        if (gen !== this.gen) return;
        this.heard = true;
        this.audioStarted = true;
        const next = this.apply({ type: "segment", ...segment });
        if (next.phase === "sent" || next.phase === "empty") { this.settleSpeech(next); return; }
        this.ports.writeBox(this.interaction === "tap"
          ? this.withDraft(transcriptOf(next)) : transcriptOf(next));
        this.publish();
      },
      onError: (code) => {
        if (gen !== this.gen) return;
        const next = this.apply({ type: "error", code });
        // "aborted" is our own stop(); the machine leaves the phase untouched for it.
        if (next.phase === "listening" || next.phase === "finalising") return;
        this.session?.abort();
        this.session = null;
        this.holding = false;
        if (next.phase === "sent" || next.phase === "empty") { this.settleSpeech(next); return; }
        this.abandon(next.notice);
      },
      onEnd: () => {
        if (gen !== this.gen) return;
        this.session = null;
        if (!this.holding) {
          // stop() has flushed everything it had; there is nothing left to wait 800 ms for.
          if (this.state.phase === "finalising") {
            this.settleSpeech(this.apply({ type: "finalised" }));
          }
          return;
        }
        if (this.restarts < 1) {
          // Safari ends a `continuous` session after a pause. One hold is one utterance, so it is
          // restarted with the finals it has already collected.
          this.restarts += 1;
          this.session = this.ports.listen(this.handlers(gen));
          if (this.session !== null || !this.holding) return;
          // Falling back mid-hold: the words the recogniser already gave us are theirs, and the
          // server's transcript continues them rather than replacing them.
          this.carried = transcriptOf(this.state);
          void this.startRecording();
          return;
        }
        this.holding = false;
        const next = this.apply({ type: "fallback" });
        if (next.phase === "sent") { this.settleSpeech(next); return; }
        this.quiet();
      },
      onAudioStart: () => {
        if (gen !== this.gen) return;
        this.audioStarted = true;
        if (!this.holding && !this.heard) this.quiet();
      },
    };
  }

  // -------------------------------------------------------------- fallback §2

  private async startRecording(): Promise<void> {
    const gen = this.gen;
    this.wantClip = true;
    this.clipState = "opening";
    this.publish();
    const handle = await this.ports.record({
      onClip: (clip) => { if (gen === this.gen) void this.consumeClip(clip); },
      onFailure: (_reason, copy) => {
        if (gen !== this.gen) return;
        this.holding = false;
        this.clipState = "none";
        this.abandon({ text: copy, ms: 0 });
      },
      onElapsed: (seconds) => {
        if (gen !== this.gen) return;
        this.elapsed = seconds;
        this.publish();
      },
    });
    if (gen !== this.gen) { handle?.cancel(); return; }
    if (handle === null) return;
    if (!this.holding) {
      // Accepting the permission sheet lifts their finger off the button.
      handle.cancel();
      if (this.clipState === "opening") { this.clipState = "none"; this.quiet(); }
      return;
    }
    this.recorder = handle;
    this.clipState = "recording";
    this.publish();
  }

  private releaseRecording(): void {
    const next = this.apply({ type: "release", at: this.releaseEventTime() });
    if (this.clipState === "recording" && this.recorder !== null) {
      if (next.phase === "idle") {
        this.wantClip = false;
        this.recorder.cancel();
        this.recorder = null;
        this.clipState = "none";
        this.abandon(next.notice);
        return;
      }
      this.clipState = "flushing";
      this.recorder.stop();
      this.recorder = null;
      this.publish();
      return;
    }
    if (this.clipState === "opening") {
      // The microphone is still opening and the user has let go: nothing is owed, and the composer
      // must not stay locked waiting for a `getUserMedia` that may never settle.
      this.clipState = "none";
      this.quiet();
      return;
    }
    // "flushing" or "transcribing": the 30 s ceiling already ended the clip and it is on its way.
    // A release now changes nothing — the clip is still theirs, and throwing it away would lose
    // thirty seconds of speech at the exact moment the user finished saying it.
    this.publish();
  }

  private async consumeClip(clip: Blob): Promise<void> {
    const gen = this.gen;
    this.recorder = null;
    this.elapsed = 0;
    if (!this.wantClip) { this.clipState = "none"; discardRun("coach-turn"); this.publish(); return; }
    // The 30 s ceiling can end a clip the user is still holding; the hop is measured from there.
    if (this.releasedAt === 0) this.releasedAt = this.now();
    this.clipState = "transcribing";
    this.publish();
    const outcome = await this.ports.transcribe(clip);
    // Cancelled while the POST was in flight: the composer belongs to nobody now.
    if (gen !== this.gen) return;
    this.clipState = "none";
    this.holding = false;
    if (!outcome.ok) { this.abandon({ text: outcome.message, ms: 0 }); return; }
    const text = outcome.text.trim();
    if (text.length === 0) { this.abandon({ text: EMPTY_COPY, ms: EMPTY_MS }); return; }
    this.closeDictation();
    // The fallback does not send: the joined turn goes in the box for them to read and tap Send.
    this.ports.writeBox(this.withDraft(text));
    this.gen += 1;
    this.showNotice(null);
    this.apply({ type: "settled" });
    this.publish();
  }

  // ---------------------------------------------------------------- settling

  private settleSpeech(next: DictationState): void {
    this.clearTimer(this.finaliseTimer);
    this.finaliseTimer = null;
    this.holding = false;
    if (next.phase !== "sent") { this.abandon(next.notice); return; }
    this.closeDictation();
    const text = this.withDraft(next.text);
    this.gen += 1;
    this.apply({ type: "settled" });
    if (this.interaction === "tap") this.ports.writeBox(text);
    this.publish();
    if (this.interaction === "hold") this.ports.send(text);
  }

  /**
   * Ruling R1: a hold does not throw away what the user had already typed. Half a sentence in the box
   * and the rest spoken is one turn — their draft, one space, the transcript. An empty draft sends
   * exactly the transcript, which is every hold that starts from an empty composer.
   */
  private withDraft(text: string): string {
    return [this.typed.trim(), this.carried.trim(), text.trim()]
      .filter((part) => part.length > 0).join(" ");
  }

  /** A hold that produced no turn: their own typed words come back and the run is forgotten. */
  private abandon(notice: DictationNotice | null): void {
    this.gen += 1;
    this.ports.writeBox(this.typed);
    discardRun("coach-turn");
    this.showNotice(notice);
    this.apply({ type: "settled" });
    this.publish();
  }

  /** Nothing happened and nothing is said about it. */
  private quiet(): void {
    this.abandon(null);
  }

  /** §4's budget: release → the transcript. It joins the run the turn's own `sent` opens. */
  private closeDictation(): void {
    markMs("coach-turn", "dictation", Math.max(0, this.now() - this.releasedAt));
  }

  // ----------------------------------------------------------------- plumbing

  private apply(event: DictationEvent): DictationState {
    this.state = nextDictation(this.state, event);
    return this.state;
  }

  private showNotice(notice: DictationNotice | null): void {
    this.clearTimer(this.noticeTimer);
    this.noticeTimer = null;
    this.notice = this.interaction === "tap" && notice?.text === EMPTY_COPY
      ? "I did not catch that. Tap Record to try again."
      : this.interaction === "tap" && notice?.text === NO_SPEECH_COPY
        ? "I did not hear anything. Tap Record to try again."
        : notice?.text ?? null;
    if (notice === null || notice.ms === 0) return;
    this.noticeTimer = this.setTimer(() => {
      this.noticeTimer = null;
      this.notice = null;
      this.apply({ type: "notice_expired" });
      this.publish();
    }, notice.ms);
  }

  private publish(): void {
    this.ports.publish(this.view());
  }

  private now(): number {
    return (this.ports.now ?? Date.now)();
  }

  private releaseEventTime(): number {
    // The hold machine treats a sub-300 ms release as an accidental tap. In tap mode the
    // second click is always deliberate, including a fast Stop after permission is denied.
    return this.interaction === "tap"
      ? Math.max(this.releasedAt, (this.state.pressedAt ?? 0) + TAP_MS)
      : this.releasedAt;
  }

  private setTimer(fn: () => void, ms: number): unknown {
    return (this.ports.setTimer ?? ((f: () => void, m: number) => setTimeout(f, m)))(fn, ms);
  }

  private clearTimer(handle: unknown): void {
    if (handle === null || handle === undefined) return;
    (this.ports.clearTimer ?? ((h: unknown) => clearTimeout(h as ReturnType<typeof setTimeout>)))(handle);
  }
}

