// @vitest-environment jsdom

import { act, cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import Composer from "@/components/coach/Composer";
import type { SpeechHandlers } from "@/lib/coach/speech-api";

const speech = vi.hoisted(() => ({ handlers: [] as SpeechHandlers[] }));
vi.mock("@/lib/coach/speech-api", () => ({
  micAvailable: () => true,
  startListening: (handlers: SpeechHandlers) => {
    speech.handlers.push(handlers);
    return { stop: vi.fn(), abort: vi.fn() };
  },
}));

afterEach(() => { cleanup(); speech.handlers.length = 0; });

describe("tap composer controls", () => {
  it("switches one main control Record → Stop → Send and waits for explicit Send", () => {
    const onSend = vi.fn();
    render(<Composer disabled={false} offline={false} onSend={onSend} />);
    const main = screen.getByRole("button", { name: "Record message" });
    fireEvent.click(main);
    expect(main.getAttribute("aria-label")).toBe("Stop recording");
    expect(main.className).toContain("coach-recording-button");
    expect(main.style.background).toBe("var(--color-alert)");
    act(() => speech.handlers[0].onSegment({ text: "I ate lunch", final: true }));
    fireEvent.click(main);
    expect(main.getAttribute("aria-label")).toBe("Send");
    expect(screen.getAllByRole("button", { name: "Send" })).toHaveLength(1);
    expect((screen.getByRole("textbox") as HTMLTextAreaElement).value).toBe("I ate lunch");
    expect(onSend).not.toHaveBeenCalled();
    fireEvent.click(main);
    expect(onSend).toHaveBeenCalledExactlyOnceWith("I ate lunch");
    expect(main.getAttribute("aria-label")).toBe("Record message");
  });

  it("preserves typed text when pointer blur precedes the Record click", () => {
    const onSend = vi.fn();
    render(<Composer disabled={false} offline={false} onSend={onSend} />);
    const input = screen.getByRole("textbox");
    fireEvent.focus(input);
    fireEvent.change(input, { target: { value: "typed first" } });
    const main = screen.getByRole("button", { name: "Record message" });
    expect(screen.getByRole("button", { name: "Send" })).not.toBe(main);
    fireEvent.pointerDown(main);
    fireEvent.blur(input, { relatedTarget: null });
    fireEvent.pointerUp(main);
    fireEvent.click(main);
    expect(main.getAttribute("aria-label")).toBe("Stop recording");
    expect(onSend).not.toHaveBeenCalled();
    act(() => speech.handlers[0].onSegment({ text: "then spoken", final: true }));
    fireEvent.click(main);
    expect(main.getAttribute("aria-label")).toBe("Send");
    expect((input as HTMLTextAreaElement).value).toBe("typed first then spoken");
    fireEvent.click(input);
    expect(main.getAttribute("aria-label")).toBe("Record message");
    expect(screen.getByRole("button", { name: "Send" })).toBeTruthy();
  });

  it("keeps the editing Send action through blur and ignores IME Enter", () => {
    const onSend = vi.fn();
    render(<Composer disabled={false} offline={false} onSend={onSend} />);
    const input = screen.getByRole("textbox");
    fireEvent.focus(input);
    fireEvent.change(input, { target: { value: "draft" } });
    const send = screen.getByRole("button", { name: "Send" });
    fireEvent.compositionStart(input);
    fireEvent.keyDown(input, { key: "Enter", code: "Enter" });
    fireEvent.compositionEnd(input);
    fireEvent.keyDown(input, { key: "Enter", code: "Enter", shiftKey: true });
    expect(onSend).not.toHaveBeenCalled();
    fireEvent.blur(input, { relatedTarget: send });
    expect(screen.getByRole("button", { name: "Send" })).toBe(send);
    fireEvent.click(send);
    expect(onSend).toHaveBeenCalledExactlyOnceWith("draft");
  });
});
